def transform(grid):
    """Restore masked cells in the framed horizontal cyclic color pattern."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The frame encodes the original outer background and border.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0 and (r < 2 or c < 2):
                out[r][c] = 1
            elif out[r][c] == 0 and (r == 2 or c == 2):
                out[r][c] = 4

    # Identify the repeating interior colors by frequency; sparse exceptional
    # seed values are not part of the regular sequence.
    counts = Counter(v for row in grid[3:] for v in row[3:] if v not in (0, 4))
    palette = sorted(v for v, n in counts.items() if n >= max(3, h // 6))
    if not palette:
        return out
    n = len(palette)
    pidx = {v: i for i, v in enumerate(palette)}

    # Find the common forward step in palette order from intact neighboring
    # cells. Adjacent samples across a zero gap also vote for the per-column step.
    votes = Counter()
    for r in range(3, h):
        known = [(c, pidx[grid[r][c]]) for c in range(3, w)
                 if grid[r][c] in pidx]
        for (c1, i1), (c2, i2) in zip(known, known[1:]):
            gap = c2 - c1
            for step in range(n):
                if (i1 + step * gap) % n == i2:
                    votes[step] += 1
                    break
    step = votes.most_common(1)[0][0] if votes else 1

    for r in range(3, h):
        anchors = [(c, pidx[grid[r][c]]) for c in range(3, w)
                   if grid[r][c] in pidx]
        if not anchors:
            continue
        for c in range(3, w):
            if out[r][c] == 0:
                ac, ai = min(anchors, key=lambda item: abs(item[0] - c))
                out[r][c] = palette[(ai + step * (c - ac)) % n]
    return out
