    colors = sorted(v for v, n in counts.items() if n >= max(4, h // 6))
    if not colors:
        return out

    # Recover the cyclic palette order from adjacent, unmasked pattern cells.
    pairs = [(grid[r][c], grid[r][c + 1])
             for r in range(3, h) for c in range(3, w - 1)
             if grid[r][c] in colors and grid[r][c + 1] in colors]
    best, best_score = tuple(colors), -1
