        if score > best_score:
            best, best_score = order, score
    pos = {v: i for i, v in enumerate(best)}

    # The pattern advances one palette step per row and per column.
    offsets = Counter((pos[grid[r][c]] - r - c) % len(best)
                      for r in range(3, h) for c in range(3, w)
                      if grid[r][c] in pos)
