from itertools import permutations


def transform(grid):
    """Restore masked cells in a framed, diagonal cyclic-color pattern."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Restore the frame/background first.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                if r < 2 or c < 2:
                    out[r][c] = 1
                elif r == 2 or c == 2:
                    out[r][c] = 4

    # Learn the recurring colors and their cyclic order from intact interior
    # neighbors. Rare colors are isolated seed/noise values, not pattern colors.
    counts = Counter(v for r in range(3, h) for v in grid[r][3:] if v)
    colors = sorted(v for v, n in counts.items() if n >= max(4, h // 6))
    if not colors:
        return out
    color_set = set(colors)
    pairs = [(grid[r][c], grid[r][c + 1])
             for r in range(3, h) for c in range(3, w - 1)
             if grid[r][c] in color_set and grid[r][c + 1] in color_set]

    # Select the cycle order that best explains horizontal neighbors.
    best = tuple(colors)
    best_score = -1
    for order in permutations(colors):
        pos = {v: i for i, v in enumerate(order)}
        score = sum(pos[b] == (pos[a] + 1) % len(order) for a, b in pairs)
        if score > best_score:
            best, best_score = order, score
    pos = {v: i for i, v in enumerate(best)}

    # The pattern advances one place in its cycle with each row and column.
    phases = Counter((pos[grid[r][c]] - r - c) % len(best)
                     for r in range(3, h) for c in range(3, w)
                     if grid[r][c] in pos)
    phase = phases.most_common(1)[0][0] if phases else 0
    for r in range(3, h):
        for c in range(3, w):
            if out[r][c] == 0:
                out[r][c] = best[(r + c + phase) % len(best)]
    return out
